// 2024 presidential margins by the congressional district used in 2024.
// The Downballot, vote tallies for each district:
// https://docs.google.com/spreadsheets/d/1ng1i_Dm_RMDnEvauH44pgE6JCUsapcuu8F2pCfeLWFo/edit?gid=1491069057
// Explainer: https://www.the-downballot.com/p/its-here-the-downballots-2024-presidential
// `trump` is Trump’s margin in points (positive means Trump won), Harris’s share minus Trump’s share, sign flipped.
// 2024 House margins are Democratic share of all ballots minus Republican share, from the
// Clerk of the House, Statistics of the Presidential and Congressional Election of November 5, 2024
// (https://clerk.house.gov/member_info/electionInfo/2024/statistics2024.pdf), via the MIT Election Data
// and Science Lab candidate file, which reprints those Clerk totals. Rounded half up to one decimal.
// Polymarket Yes prices are the Gamma API snapshot at 8:18 p.m. CT on October 31, 2026
// (2026-10-31T20:18:25-05:00), rounded half up to one decimal percent.
// FiftyPlusOne’s public averages page publishes Senate and governor averages, not a House district average.

export const HOUSE_POLYMARKET_AS_OF = "October 31, 2026, 8:18 p.m. CT";
export const HOUSE_PRES_SOURCE = "https://docs.google.com/spreadsheets/d/1ng1i_Dm_RMDnEvauH44pgE6JCUsapcuu8F2pCfeLWFo/edit?gid=1491069057#gid=1491069057";
export const HOUSE_PRES_PAGE = "https://www.the-downballot.com/p/its-here-the-downballots-2024-presidential";
export const HOUSE_RESULT_SOURCE = "https://clerk.house.gov/member_info/electionInfo/2024/statistics2024.pdf";
export const HOUSE_NOMINATION_SOURCE = "https://clerk.house.gov/member_info/electionInfo/2026/120-nominations.pdf";
export const HOUSE_CA_CANDIDATE_SOURCE = "https://ballotpedia.org/United_States_House_of_Representatives_elections_in_California,_2026";

export type HouseFigure = "general" | "fusion" | "top-two" | "jungle" | "first-round" | "none";
export type HouseResult2024 = {
  marginD: number | null;
  demPct: number | null;
  repPct: number | null;
  figure: HouseFigure;
  note: string;
};
export type HousePerson = {
  name: string;
  party: "D" | "R" | "I";
  label: string;
  /** Polymarket Yes price, in percent. */
  price: number;
};
export type HouseMarket = {
  slug: string;
  candidates: HousePerson[];
  caveat?: string;
  /** Party-contract prices used only when the named market has no Democrat and no Republican. */
  partyColor?: { dem: number; rep: number; margin: number };
};

